import sys
from itertools import combinations

s = sys.stdin.read().split()[0]
n = len(s)
best = None
for k in range(0, 3):
    for cuts in combinations(range(1, n), k):
        bounds = [0] + list(cuts) + [n]
        pieces = [s[bounds[i]:bounds[i + 1]] for i in range(len(bounds) - 1)]
        ok = False
        for mask in range(1 << len(pieces)):
            a1 = b1 = a2 = b2 = 0
            for idx, pc in enumerate(pieces):
                if mask >> idx & 1:
                    a1 += pc.count('a')
                    b1 += pc.count('b')
                else:
                    a2 += pc.count('a')
                    b2 += pc.count('b')
            if a1 == a2 and b1 == b2:
                ok = True
                break
        if ok:
            key = (len(cuts), cuts)
            if best is None or key < best:
                best = key
print(' '.join(map(str, best[1])))

